+import { useQuestionsByVotes } from "../questions/useQuestionsByVotes.ts";
+import { FeaturedSession } from "./FeaturedSession.tsx";
+
+interface Props {
+  session: SessionSummary;
+}
+
+// The card waits for its polls and, when they are on, its questions, so it
+// appears whole instead of filling in by parts.
+export const HomeFeaturedSession = ({ session }: Props) => {
+  const polls = usePolls({ sessionId: session.id, status: "active" });
+  const questions = useQuestionsByVotes(session.id, { enabled: session.featuredQuestions });
+
+  return polls.data == null || (session.featuredQuestions && questions.data == null) ? (
+    <SkeletonOf>
+      <FeaturedSession
+        session={session}
+        polls={[pollExamples[0]]}
+        questions={session.featuredQuestions ? questionExamples : undefined}
+      />
+    </SkeletonOf>
+  ) : (
+    <FeaturedSession
+      session={session}
+      polls={polls.data}
+      questions={session.featuredQuestions ? questions.data : undefined}
+    />
+  );
+};
